sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var sysId   = request.queryParams.sys_id;
    var action  = request.queryParams.action;
    var userId  = gs.getUserID(); // email user

    if (!sysId || !action) {
        response.setBody({ success: false, error: "Missing parameters" });
        return;
    }

    var gr = new GlideRecord('x_birl3_clm_clm_new_credit_request');
    if (!gr.get(sysId)) {
        response.setBody({ success: false, error: "Record not found" });
        return;
    }

    var comments = "Action via Email";

    // 🔥 SAME LOGIC AS YOUR WIDGET
    function syncFlowApproval(requestSysId, decision, comments) {
        var apGr = new GlideRecord('sysapproval_approver');
        apGr.addQuery('document_id', requestSysId);
        apGr.addQuery('state', 'requested');
        apGr.query();

        while (apGr.next()) {
            if (decision === 'approve') {
                apGr.state = 'approved';
            } else {
                apGr.state = 'rejected';
            }
            apGr.comments = comments;
            apGr.update();
        }
    }

    if (action === 'approve') {
        syncFlowApproval(sysId, 'approve', comments);
    } 
    else if (action === 'reject') {
        syncFlowApproval(sysId, 'reject', comments);
    } 
    else if (action === 'return') {
        syncFlowApproval(sysId, 'reject', "Returned via email");
    }

    response.setBody({
        success: true,
        message: "Action completed"
    });

})(request, response);
